#include <bits/stdc++.h>
using namespace std;
typedef pair<long long,long long> P;
long long cross(P O,P A,P B){return(A.first-O.first)*(B.second-O.second)-(A.second-O.second)*(B.first-O.first);}
vector<P> convexHull(vector<P> pts){
    int n=pts.size(),k=0;
    sort(pts.begin(),pts.end());
    vector<P> h(2*n);
    for(int i=0;i<n;i++){while(k>=2&&cross(h[k-2],h[k-1],pts[i])<=0)k--;h[k++]=pts[i];}
    for(int i=n-2,t=k+1;i>=0;i--){while(k>=t&&cross(h[k-2],h[k-1],pts[i])<=0)k--;h[k++]=pts[i];}
    return vector<P>(h.begin(),h.begin()+k-1);
}
